import{_ as a,o,c as t,a2 as s}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Desktop Installation","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/desktop.md","filePath":"self-hosted/desktop.md","lastUpdated":1785920317000}'),n={name:"self-hosted/desktop.md"};function r(i,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="desktop-installation" tabindex="-1">Desktop Installation <a class="header-anchor" href="#desktop-installation" aria-label="Permalink to &quot;Desktop Installation&quot;">​</a></h1><p>Memoh Desktop is the native client for personal and local use. It is separate from the server deploy stack: the desktop app manages its own local backend instead of connecting to a hosted Web/server deployment by default.</p><h2 id="when-to-use-desktop" tabindex="-1">When to use Desktop <a class="header-anchor" href="#when-to-use-desktop" aria-label="Permalink to &quot;When to use Desktop&quot;">​</a></h2><p>Choose Desktop when you want:</p><ul><li>a local app that starts Memoh for you</li><li>single-user or personal workflows</li><li>local memory and local storage</li><li>a bundled <code>memoh</code> CLI connected to the same local server</li><li>local or Docker-backed workspaces from your own machine</li></ul><p>Choose <a href="/self-hosted/docker.html">Server Deploy</a> instead when you need shared access, production uptime, remote users, or messaging channels that should keep running while your desktop is offline.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Download the installer for your platform from the <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">Memoh Desktop download page</a>.</li><li>Open Memoh.</li><li>Let the app start its local server and initialize storage.</li><li>Optional: use the app menu to install the bundled <code>memoh</code> CLI.</li></ol><h2 id="what-desktop-manages" tabindex="-1">What Desktop manages <a class="header-anchor" href="#what-desktop-manages" aria-label="Permalink to &quot;What Desktop manages&quot;">​</a></h2><p>Desktop owns the local runtime lifecycle:</p><ul><li>local <code>memoh-server</code> on <code>127.0.0.1:18731</code></li><li>SQLite-backed local data under the OS application data directory</li><li>embedded Qdrant for memory vector search</li><li>bundled CLI, server binary, provider templates, and workspace bridge runtime</li><li>system tray reopen and quit behavior</li></ul><p>Quitting from the tray follows the desktop shutdown path and stops the managed local server and embedded Qdrant.</p><h2 id="connecting-to-a-remote-server" tabindex="-1">Connecting to a remote server <a class="header-anchor" href="#connecting-to-a-remote-server" aria-label="Permalink to &quot;Connecting to a remote server&quot;">​</a></h2><p>Desktop can also act as a client for a <a href="/self-hosted/docker.html">Server Deploy</a> instead of running its own local backend. On the connect screen, enter the server address and connect:</p><ul><li>A bare domain such as <code>memoh.example.com</code> is assumed to be <code>https://</code> (only localhost addresses default to <code>http://</code>).</li><li>The <code>/api</code> path suffix is appended automatically when missing — entering just the domain is enough.</li><li>Desktop probes the server&#39;s <code>/ping</code> endpoint (5-second timeout) before proceeding, then takes you to sign-in.</li></ul><p>Switching to a different server clears the local sign-in state, so you will authenticate against the new server.</p><h2 id="sharing-this-computer-with-bots" tabindex="-1">Sharing this computer with bots <a class="header-anchor" href="#sharing-this-computer-with-bots" aria-label="Permalink to &quot;Sharing this computer with bots&quot;">​</a></h2><p>Desktop can register the machine it runs on as a <strong>Computer</strong> that server-side bots can work on, without running a separate runtime process. Enable <strong>This computer</strong>, give it a name, and Desktop keeps the connection alive in the background. See <a href="/guides/computers.html">Computers</a> for the permission model and per-bot setup.</p><h2 id="workspace-behavior" tabindex="-1">Workspace behavior <a class="header-anchor" href="#workspace-behavior" aria-label="Permalink to &quot;Workspace behavior&quot;">​</a></h2><p>Desktop can use trusted local workspaces and container-backed workspaces depending on configuration and runtime availability. Trusted local workspaces run with local user permissions and are not container-isolated. Container-backed workspaces keep the normal bot workspace model for file editing, command execution, MCP hosting, and optional display/browser sessions.</p><p>For runtime details, see <a href="/self-hosted/workspace-backends.html">Workspace Backends</a>.</p>',21)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
